content.content:
	// WEB3 API Configuration — shared by web3_item (POST /claim) and web3_token
	// (POST /claim/erc20). An empty WEB3_BASE_URL disables both paths, because
	// NewWEB3Client returns nil and both handlers guard on it.
	WEB3BaseURL string `arg:"env:WEB3_BASE_URL"`
	// WEB3ERC20Project is the IGS project id the minting service resolves the
	// (project, sku) pair against to pick the ERC-20 contract. We never send the
	// token address — it comes from the service's own ERC20_TOKENS config.
	WEB3ERC20Project string `arg:"env:WEB3_ERC20_PROJECT"`
	WEB3APIKey       string `arg:"env:WEB3_API_KEY"`

---
	logger *logrus.Entry,
) (string, error) {
	logger.Info("Processing Web3 token reward")

	if a.web3Client == nil {
		logger.WithFields(logrus.Fields{"action": "web3_client_not_configured", "status": "failed"}).Error("WEB3 client is not configured")
		return "", temporal.NewNonRetryableApplicationError(
			"web3 client is not configured", "Web3TokenNotConfigured", nil)
	}

	if config.Props.WEB3ERC20Project == "" {
		logger.WithFields(logrus.Fields{"action": "web3_erc20_project_not_configured", "status": "failed"}).
			Error("WEB3_ERC20_PROJECT is not configured")
		return "", temporal.NewNonRetryableApplicationError(
			"web3 erc20 project is not configured", "Web3TokenNotConfigured", nil)
	}

	web3TokenBody, err := rewardParams.AsWeb3Token()
	if err != nil {
		logger.WithFields(logrus.Fields{"action": "parse_web3_token_body", "status": "failed", "error": err}).Error("Failed to parse web3_token body")
		// A malformed body is a quest-config problem: it will never parse on a retry.
		return "", temporal.NewNonRetryableApplicationError(
			"failed to parse web3_token body", "Web3TokenInvalidBody", err)
	}

	xsollaID, err := helper.RequireUserID(&params.Event, event.IdentifierTypeXsollaId, logger, "missing_xsolla_id", "xsolla_id")
	if err != nil {
		return "", err
	}

	wallet, err := a.resolveWeb3Wallet(ctx, xsollaID, web3TokenBody.ItemSKU, logger)
---
	}
	if walletAddress == "" {
		return nil, fmt.Errorf("web3 claim erc20: no wallet address provided")
	}
	if amount <= 0 {
		return nil, fmt.Errorf("web3 claim erc20: amount must be positive")
	}

	payload := claimERC20Payload{
		Address: walletAddress,
		SKU:     itemSku,
		Amount:  strconv.FormatFloat(amount, 'f', -1, 64),
		Project: c.config.ERC20Project,
	}

	baseLogger := log.WithFields(logrus.Fields{
		"component":      LogFieldComponent,
		"feature":        LogFieldFeature,
		"action":         LogFieldActionClaimERC20,
		"wallet_address": walletAddress,
		"sku":            itemSku,
---
