func (c qpDataClient) listQuests(ctx context.Context) ([]qpDataQuest, error) {
	var all []qpDataQuest
	for page := 1; page <= 20; page++ {
		var resp qpDataQuestsPage
		// In-cluster qp-data serves the internal /api/v1 prefix (the doc's external
		// /quests/data/v1/X maps to internal /api/v1/X). The quests-list endpoint isn't
		// deployed to stage yet (only /api/v1/quest-executions exists); until it lands,
		// this 404s and the provider falls back to mock.
		path := fmt.Sprintf("/api/v1/quests?size=200&page=%d", page)
		if err := c.get(ctx, path, &resp); err != nil {
			return nil, err
		}
		all = append(all, resp.Items...)

