package handler

import (
	"context"
	"net/http"
	"questengine/internal/config"
	"questengine/internal/http/middleware"
	"questengine/internal/service"

	"github.com/danielgtaylor/huma/v2"
	gq "gitlab.loc/adtech/adtech/lib/models/v2/generic_quest"
	qpErrors "gitlab.loc/adtech/adtech/lib/qp_errors"
	"gitlab.loc/adtech/adtech/lib/qp_errors/resolver"
)

type ledgerRoutes struct {
	ledgerService service.LedgerService
}

func AddLedgerRoutes(api huma.API, tag string, ledgerService service.LedgerService, apiKeyMiddleware func(ctx huma.Context, next func(huma.Context))) {
	routes := &ledgerRoutes{
		ledgerService: ledgerService,
	}
	huma.Register(
		api, huma.Operation{
			OperationID: "getLedgerSessions",
			Method:      http.MethodGet,
			Path:        config.ApiPrefixV1 + "/ledger/sessions",
			Summary:     "Retrieve a paginated list of ledger sessions",
			Description: "Retrieve a paginated list of ledger sessions",
			Middlewares: huma.Middlewares{apiKeyMiddleware},
			Tags:        []string{tag},
		}, routes.getLedgerSessions,
	)
}

func (lr *ledgerRoutes) getLedgerSessions(ctx context.Context, req *gq.LedgerSessionsRequestPayload) (*gq.LedgerSessionsListResponseDTO, error) {
	accountID, ok := middleware.GetAccountIDFromContext(ctx)
	if !ok {
		return nil, resolver.Resolve(qpErrors.Unauthorized("Account ID not found in context"))
	}

	response, err := lr.ledgerService.ListLedgerSessions(ctx, accountID, req)
	if err != nil {
		return nil, resolver.Resolve(err)
	}

	return &gq.LedgerSessionsListResponseDTO{
		Body: *response,
	}, nil
}
