func ValidateAPIKeyMiddleware(validator service.APIKeyValidator) func(ctx huma.Context, next func(huma.Context)) {
	return func(ctx huma.Context, next func(huma.Context)) {
		log := qp_logger.LoggerFromCtx(ctx.Context())

		apiKey := ctx.Header(ApiKeyHeaderName)
		if apiKey == "" {
			log.WithFields(logrus.Fields{"action": "validate_api_key.missing_header"}).
				Warnf("%s header is required", ApiKeyHeaderName)
			writeUnauthorizedResponse(ctx, ApiKeyHeaderName+" header is required")
			return
		}

		accountID, err := validator.ValidateAPIKey(ctx.Context(), apiKey)
		if err != nil {
			log.WithFields(logrus.Fields{"action": "validate_api_key.failed", "error": err}).
				Warn("API key validation failed")
			writeUnauthorizedResponse(ctx, "Invalid or inactive API key")
			return
		}

		log.WithFields(logrus.Fields{
			"action":     "validate_api_key.success",
			"account_id": accountID,
		}).Debug("API key validated successfully")

		ctx = huma.WithValue(ctx, AccountIDContextKey, accountID)
		next(ctx)
	}
}

func writeUnauthorizedResponse(ctx huma.Context, message string) {
	ctx.SetStatus(401)
	ctx.SetHeader("Content-Type", "application/json")
	if _, err := ctx.BodyWriter().Write([]byte(`{"error":"` + message + `"}`)); err != nil {
		qp_logger.LoggerFromCtx(ctx.Context()).WithError(err).
			Error("Failed to write unauthorized response")
	}
