func AddQuestInfoRoutes(api huma.API, tag string, questInfoService service.QuestInfoService, apiKeyMiddleware func(ctx huma.Context, next func(huma.Context))) {
	routes := &questInfoRoutes{questInfoService: questInfoService}
	huma.Register(
		api, huma.Operation{
			OperationID: "getQuestInfo",
			Method:      http.MethodGet,
			Path:        config.ApiPrefixV1 + "/quests/info",
			Summary:     "Retrieve quest info for a user including not-yet-triggered quests",
			Description: "Returns all quests relevant to the account with per-user execution status. Quests with no execution history are returned with status NOT_TRIGGERED.",
			Middlewares: huma.Middlewares{apiKeyMiddleware},
			Tags:        []string{tag},
		}, routes.getQuestInfo,
	)
}

func (r *questInfoRoutes) getQuestInfo(ctx context.Context, req *gq.QuestInfoRequestPayload) (*gq.QuestInfoListResponseDTO, error) {
	accountID, ok := middleware.GetAccountIDFromContext(ctx)
	if !ok {
		return nil, resolver.Resolve(qpErrors.Unauthorized("Account ID not found in context"))
	}

