// initTemporalClient creates the Temporal client and workflow service.
// When TEMPORAL_DISABLED=true, returns a no-op workflow service for load testing.
func initTemporalClient(
	infra *InfraDeps,
	repos *RepoDeps,
	svcs *ServiceDeps,
) (client.Client, port.WorkflowStarter, func(), error) {
	if config.Props.TemporalDisabled {
		qp_logger.Logger.Warn("TEMPORAL_DISABLED=true: all workflow scheduling bypassed. FOR LOAD TESTING ONLY.")
		return nil, &temporal.NoOpWorkflowService{}, nil, nil
	}

	temporalClient, err := temporal.New(temporal.TemporalDeps{
		ConversionActivities: svcs.ConversionActivities,
		CounterRepo:          repos.Counter,
		LedgerRepo:           repos.Ledger,
		RewardService:        svcs.RewardService,
		KafkaProducer:        infra.OfwProducer,
		TelemetryCfg:         infra.TelemetryCfg,
		RedisStorage:         infra.RedisStorage,
		TokenCacheProvider:   [REDACTED:credential],
		ClickhouseDB:         infra.ClickHouse,
		WebhookAdapter:       svcs.WebhookAdapter,
	})
	if err != nil {
		return nil, nil, nil, fmt.Errorf("temporal: %w", err)
	}

	return temporalClient, temporal.NewWorkflowService(temporalClient), func() { temporalClient.Close() }, nil
}

func initKafkaConsumers(
	ctx context.Context,
	infra *InfraDeps,
	repos *RepoDeps,
	workflowService port.WorkflowStarter,
	healthChecker *qp_health_check.HealthChecker,
) (qpConsumer, ofwConsumer kafka.ConsumerManager, cleanups []func(), err error) {
	var redisClient goredis.UniversalClient
	if infra.RedisClient != nil {
		redisClient = infra.RedisClient.GetClient()
	}

	qpConsumer, err = kafka.InitQPConsumerManager(ctx, infra.TelemetryCfg, repos.UserOffer, workflowService, repos.PublisherBannedUser, healthChecker, redisClient)
	if err != nil {
		return nil, nil, nil, fmt.Errorf("qp consumer manager: %w", err)
	}
	cleanups = append(cleanups, func() {
		if err := qpConsumer.Stop(); err != nil {
			qp_logger.Logger.WithError(err).Error("Failed to stop QP consumer manager")
		}
	})

	ofwConsumer, err = kafka.InitOfwConsumerManager(ctx, infra.TelemetryCfg, repos.UserOffer, workflowService, repos.PublisherBannedUser, healthChecker)
	if err != nil {
		return nil, nil, cleanups, fmt.Errorf("ofw consumer manager: %w", err)
	}
