package web3_api

type WEB3ClientConfig struct {
	BaseURL string
	// ERC20Project is the IGS project id for POST /claim/erc20 (e.g. "306916" on stage).
	ERC20Project string
}

// mintErrorResponse is the error envelope the web3-minting-service returns on non-2xx.
type mintErrorResponse struct {
	Error   string `json:"error"`
	Message string `json:"message,omitempty"`
}

// WalletResponse is the GET /wallet/{user} success payload.
type WalletResponse struct {
	User            string `json:"user"`
	WalletAddress   string `json:"walletAddress"`
	RecipientSource string `json:"recipientSource"`
	ThirdwebUserID  string `json:"thirdwebUserId"`
}

type mintItemPayload struct {
	User   string `json:"user"`
	SKU    string `json:"sku"`
	Amount int    `json:"amount"`
}

